}

/* Enables auto-fitting columns with a default minmax range */
[data-lk-component="grid"][data-lk-grid-minmax="true"] {
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
}

/* Overrides default min width in minmax range */
[data-lk-component="grid"][data-lk-grid-minmax="true"][data-lk-grid-minmax-minwidth="3xs"] {
  grid-template-columns: repeat(auto-fit, minmax(var(--lk-size-3xs), 1fr));
