/* Collapse to single column on mobile viewports (portrait) */
@media (max-width: 480px) {
  [data-lk-component="grid"][data-lk-grid-auto-responsive="true"] {
    grid-template-columns: 1fr !important;
  }

  /* Force all children to single span (use !important to override combinations) */
  [data-lk-component="grid"][data-lk-grid-auto-responsive="true"]>* {
    grid-column: span 1 !important;
  }
}

/* Sets gap using LiftKit spacing scale */
[data-lk-component="grid"][data-lk-grid-gap="3xs"] {
